import java.util.*;

class Solution {
    public int longestSubarray(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        int left = 0, repeated = 0, ans = 0;

        for (int right = 0; right < nums.length; right++) {
            freq.put(nums[right], freq.getOrDefault(nums[right], 0) + 1);

            if (freq.get(nums[right]) == 2)
                repeated++;

            while (repeated > k) {
                freq.put(nums[left], freq.get(nums[left]) - 1);

                if (freq.get(nums[left]) == 1)
                    repeated--;

                left++;
            }

            ans = Math.max(ans, right - left + 1);
        }

        return ans;
    }
}

class Solution {
    public int earliestFinishTime(int[] landStart, int[] landDur,
                                  int[] waterStart, int[] waterDur) {
        int ans = Integer.MAX_VALUE;

        for (int i = 0; i < landStart.length; i++) {
            int landEnd = landStart[i] + landDur[i];

            for (int j = 0; j < waterStart.length; j++) {
                int start = Math.max(landEnd, waterStart[j]);
                ans = Math.min(ans, start + waterDur[j]);
            }
        }

        return ans;
    }
}

import java.util.*;

class Solution {
    public int maxWeight(int[] weights) {
        Arrays.sort(weights);

        int n = weights.length;
        int bag1 = 0, bag2 = 0;

        for (int i = 0; i < n / 2; i++)
            bag1 += weights[n - 1 - i];

        for (int i = n / 2; i < n; i++)
            bag2 += weights[n - 1 - i];

        return Math.abs(bag1 - bag2);
    }
}

class Solution {
    public int maxBalancedShipments(int[] weight) {
        int ans = 0;
        int mn = weight[0];

        for (int i = 1; i < weight.length; i++) {
            if (weight[i] > mn) {
                ans++;
                mn = Integer.MAX_VALUE;
            } else {
                mn = Math.min(mn, weight[i]);
            }
        }

        return ans;
    }
}

class Solution {
    public int trionic(int[] nums) {
        int n = nums.length;
        int[] inc = new int[n];
        int[] dec = new int[n];

        Arrays.fill(inc, 1);
        Arrays.fill(dec, 1);

        for (int i = 1; i < n; i++) {
            if (nums[i] > nums[i - 1])
                inc[i] = inc[i - 1] + 1;
        }

        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] > nums[i + 1])
                dec[i] = dec[i + 1] + 1;
        }

        int ans = 0;

        for (int i = 0; i < n; i++)
            ans = Math.max(ans, inc[i] + dec[i] - 1);

        return ans;
    }
}

class Solution {
    private boolean isPalindrome(long n) {
        long rev = 0, temp = n;

        while (temp > 0) {
            rev = rev * 10 + temp % 10;
            temp /= 10;
        }

        return rev == n;
    }

    public long nextPalindrome(long n) {
        n++;

        while (!isPalindrome(n))
            n++;

        return n;
    }
}

import java.util.*;

class Solution {
    public int[][] sortThreats(int[][] threats) {
        Arrays.sort(threats, (a, b) -> {
            if (a[0] != b[0])
                return b[0] - a[0];
            return b[1] - a[1];
        });

        return threats;
    }
}
